def __getattr__(name: str) -> Any:
    try:
        module_name = _MODEL_MODULES[name]
    except KeyError:
        raise AttributeError(f"module {__name__!r} has no attribute {name!r}") from None
    value = getattr(import_module(f"{__name__}.{module_name}"), name)
    globals()[name] = value
    return value
